// ============================================
// VALIDATION INPUT - MCP Text Embedder (multi-provider)
// providers: openai | mistral | gemini
// ============================================
const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

const errors = [];
const text = body.text || ctx.text;
const provider = (body.provider || ctx.provider || 'openai').toLowerCase();

const DEFAULT_MODEL = {
  openai: 'text-embedding-3-small',
  mistral: 'mistral-embed',
  gemini: 'text-embedding-004'
};
const model = body.model || ctx.model || DEFAULT_MODEL[provider];
const dimensions = body.dimensions || ctx.dimensions || 1536;

const apiKey = body.api_key || ctx.api_key
  || body[provider + '_api_key'] || ctx[provider + '_api_key']
  || body.openai_api_key || ctx.openai_api_key;

const VALID = ['openai', 'mistral', 'gemini'];
if (!text) errors.push('text requis (string ou array de strings)');
if (!VALID.includes(provider)) errors.push("provider invalide: '" + provider + "' (openai, mistral, gemini)");
if (!apiKey) errors.push('api_key requis (ou openai_api_key / mistral_api_key / gemini_api_key)');

if (errors.length > 0) {
  return { valid: false, errors: errors, provider: provider, model: model,
    user_id: userId, guild_id: guildId, user_request: userRequest };
}

const inputs = Array.isArray(text) ? text : [text];

// precompute pour les templates des nodes HTTP
const gModel = model.indexOf('models/') === 0 ? model : 'models/' + model;
const geminiRequests = inputs.map(function (t) {
  const r = { model: gModel, content: { parts: [{ text: t }] } };
  if (dimensions) r.outputDimensionality = dimensions;
  return r;
});

return {
  valid: true,
  provider: provider,
  model: model,
  dimensions: dimensions,
  api_key: apiKey,
  input_json: JSON.stringify(inputs),            // openai/mistral: "input": {{ input_json }}
  gemini_model_path: gModel,                      // gemini URL
  gemini_requests_json: JSON.stringify(geminiRequests), // gemini body
  user_id: userId, guild_id: guildId, user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// FORMAT OPENAI RESPONSE - MCP Text Embedder
// Enveloppe de sortie IDENTIQUE quel que soit le provider.
// ============================================
const j = $input.first().json || {};
const v = $('Validate Input').first().json;
const latencyMs = Date.now() - (v.startTime || Date.now());

if (j.error) {
  const e = j.error || {};
  return {
    success: false,
    error: { code: e.code || 'OPENAI_ERROR', message: e.message || j.message || j.detail || 'openai API error', status: 'API_ERROR' },
    meta: { provider: 'openai', model: v.model },
    user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request,
    _trace: { service_response: { error: (j.error || j.message || j.detail) }, provider: 'openai', model: v.model, mode: 'error', latency_ms: latencyMs, user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request }
  };
}

try {
    const arr = j.data || [];
    const embeddings = arr.map(function (e, i) {
      const emb = e.embedding || [];
      return { index: (e.index != null ? e.index : i), embedding: emb, dimensions: emb.length };
    });
    const usage = j.usage || {};
    const respModel = j.model || v.model;
  const responseData = { embeddings: embeddings, count: embeddings.length, model: respModel, dimensions: (embeddings[0] && embeddings[0].dimensions) || 0 };
  return {
    success: true,
    data: responseData,
    meta: { provider: 'openai', model: respModel, usage: usage },
    user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request,
    _trace: { service_response: responseData, provider: 'openai', model: respModel, mode: 'success', latency_ms: latencyMs, token_usage: usage, user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request }
  };
} catch (err) {
  return {
    success: false,
    error: { code: 500, message: 'Failed to parse embeddings response: ' + err.message, status: 'PARSE_ERROR' },
    meta: { provider: 'openai', model: v.model },
    user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request,
    _trace: { service_response: { parse_error: err.message }, provider: 'openai', model: v.model, mode: 'error', latency_ms: latencyMs, user_id: v.user_id, guild_id: v.guild_id, user_request: v.user_request }
  };
}

